def test_recursive_unicode_converts_bytes_in_nested_structures_including_keys():
    obj = {
        b'a': [b'1', {'inner': b'2'}],
        'b': (b'3', 4, {b'c': b'5'}),
    }

    out = recursive_unicode(obj)

    expected = {
        'a': ['1', {'inner': '2'}],
        'b': ('3', 4, {'c': '5'}),
    }

    assert out == expected

    # Ensure that bytes keys were converted to strings in the output
    assert all(isinstance(k, str) for k in out.keys())

    # The original input should remain unchanged
    assert obj == {
        b'a': [b'1', {'inner': b'2'}],
        'b': (b'3', 4, {b'c': b'5'}),
    }


def test_recursive_unicode_preserves_structure_types_for_mixed_nested_types():
    obj = {'a': [b'one', (b'two', 3)], 'b': (b'three', {'c': [b'four']})}
    out = recursive_unicode(obj)

    expected = {
        'a': ['one', ('two', 3)],
        'b': ('three', {'c': ['four']}),
    }

    assert out == expected

    # Ensure types are preserved: lists, tuples, and dicts
    assert isinstance(out, dict)
    assert isinstance(out['a'], list)
    assert isinstance(out['a'][1], tuple)
    assert isinstance(out['b'], tuple)
    assert isinstance(out['b'][1], dict)


def test_recursive_unicode_handles_only_unicode_strings_and_no_bytes():
    obj = {'a': 'string', 'b': [1, 'two'], 'c': (True, 3)}
    out = recursive_unicode(obj)

    assert out == obj

