from tornado.platform.asyncio import BaseAsyncIOLoop


class TrackFD:
    def __init__(self, name: str):
        self.name = name
        self.closed = False
        self.close_calls = 0

    def fileno(self):
        # Return a dummy valid file descriptor number
        return (hash(self.name) & 0xFFFF)

    def close(self):
        self.closed = True
        self.close_calls += 1


class DummyLoop:
    def __init__(self, name: str):
        self.name = name
        self.closed = False
        self.close_calls = 0
        self.raise_on_close = False

    def close(self):
        self.close_calls += 1
        self.closed = True
        if self.raise_on_close:
            raise RuntimeError("close error")


def test_close_basic_sets_flag_closes_loops_and_clears_handlers():
    loop = object.__new__(BaseAsyncIOLoop)

    loop.closing = False
    fd1 = TrackFD("fd1")
    fd2 = TrackFD("fd2")
    loop.handlers = {
        "h1": (fd1, None),
        "h2": (fd2, None),
    }
    loop.readers = {}
    loop.asyncio_loop = DummyLoop("asyncio")
    loop.selector_loop = DummyLoop("selector")

    loop.close(all_fds=False)

    assert loop.closing is True
    assert loop.asyncio_loop.close_calls == 1
    assert loop.selector_loop.close_calls == 1
    assert fd1.close_calls == 0
    assert fd2.close_calls == 0
    assert loop.handlers == {}


