    # Simulate Windows environment
    FakeOS = types.SimpleNamespace(name='nt')
    monkeypatch.setattr(proc, 'os', FakeOS)
    with pytest.raises(RuntimeError):
        proc.fork_processes(None)

def test_child_path_exits_simulated(monkeypatch):
    # Simulate a single child path being executed
    class FakeOS:
        name = 'posix'
        call_count = 0

        @staticmethod
        def fork():
            FakeOS.call_count += 1
            # First call simulates child path (pid == 0)
            return 0 if FakeOS.call_count == 1 else 1

        @staticmethod
        def _exit(code):
            raise SystemExit(code)

        @staticmethod
        def waitpid(pid, options):
            return (0, 0)

    monkeypatch.setattr(proc, 'os', FakeOS)
    monkeypatch.setattr(proc, 'cpu_count', lambda: 1)
    with pytest.raises(SystemExit) as exc:
        proc.fork_processes(None)
    assert exc.value.code == 0

